11→function fixture(before, after, opts = {}) {
12→  const beforeRoot = dir('cpg-before'); const afterRoot = dir('cpg-after'); const artifacts = dir('cpg-delta-artifacts');
13→  write(beforeRoot, 'src/a.js', before); write(afterRoot, 'src/a.js', after);
14→  const atlas = new AtlasCpgDelta({ artifactRoot: artifacts, maxSourceBytes: 64 * 1024, maxGraphBytes: 512 * 1024, maxDeltaBytes: 512 * 1024, maxImpactDepth: 8, maxReachDefPairs: 4096, ...opts });
15→  return { beforeRoot, afterRoot, artifacts, atlas, args: { beforePath: 'src/a.js', afterPath: 'src/a.js', impactDepth: 4 }, ctx: { beforeRoot, afterRoot, budgetTokens: 10000 } };
