18→test('CD1/CD2: identical semantics with moved formatting produces an empty delta', async () => {
19→  const f = fixture(`function helper(x){return x}\n`, `function helper ( x ) {\n  return x\n}\n`);
20→  const result = await f.atlas.invoke('cpg.delta', f.args, f.ctx);
21→  assert.equal(result.status, 'ok'); assert.deepEqual(result.provenance.counts, { nodesAdded: 0, nodesRemoved: 0, nodesModified: 0, edgesAdded: 0, edgesRemoved: 0, impacted: 0 });
22→});
