24→test('CD3/CD4: syntax and call changes classify and propagate impact to callers', async () => {
25→  const before = `function helper(x) { return x }\nfunction run(v) { let out = helper(v); return out }\n`;
26→  const after = `function helper(x) { let y = x + 1; return y }\nfunction run(v) { let out = helper(v); return out }\n`;
27→  const f = fixture(before, after); const result = await f.atlas.invoke('cpg.delta', f.args, f.ctx); const artifact = JSON.parse(readFileSync(result.refs[0].path, 'utf8'));
28→  assert.ok(result.provenance.counts.nodesModified > 0); assert.ok(result.provenance.counts.nodesAdded > 0);
29→  assert.equal(artifact.impact.some((item) => item.nodeKey.includes('function:helper')), true);
30→  assert.equal(artifact.impact.some((item) => item.nodeKey.includes('function:run') && item.reason === 'caller'), true);
31→  assert.equal(artifact.nodeChanges.some((item) => item.change === 'modified' && item.after?.type === 'statement'), true);
32→});
