34→test('CD2/CD5: rename is remove/add and unresolved calls do not fabricate caller impact', async () => {
35→  const f = fixture(`function helper(x) { return x }\nfunction run(v) { return helper(v) }\n`, `function assist(x) { return x }\nfunction run(v) { return dynamic(v) }\n`);
36→  const result = await f.atlas.invoke('cpg.delta', f.args, f.ctx); const artifact = JSON.parse(readFileSync(result.refs[0].path, 'utf8'));
37→  assert.equal(artifact.nodeChanges.some((item) => item.change === 'removed' && item.before?.name === 'helper'), true);
38→  assert.equal(artifact.nodeChanges.some((item) => item.change === 'added' && item.after?.name === 'assist'), true);
39→  assert.equal(artifact.impact.some((item) => item.reason === 'caller' && item.nodeKey.includes('dynamic')), false);
40→});
