import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { AtlasCpgSlice, AtlasCpgTaint, AtlasCpgDelta } from './src/index.mjs';

function setup(source, opts={}) {
  const root = mkdtempSync(join(tmpdir(), 'probe-root-'));
  const artifacts = mkdtempSync(join(tmpdir(), 'probe-art-'));
  mkdirSync(join(root,'src'),{recursive:true});
  writeFileSync(join(root,'src/a.js'), source);
  const common = { maxSourceBytes: 64*1024, maxReachDefPairs: 4096, ...opts };
  const cpg = new AtlasCpgSlice({ artifactRoot: join(artifacts,'cpg'), maxArtifactBytes: 512*1024, ...common });
  const taint = new AtlasCpgTaint({ artifactRoot: join(artifacts,'taint'), maxGraphBytes: 512*1024, maxResultBytes: 512*1024, maxDepth: 24, maxPaths: 32, ...common });
  const delta = new AtlasCpgDelta({ artifactRoot: join(artifacts,'delta'), maxGraphBytes: 512*1024, maxDeltaBytes: 512*1024, maxImpactDepth: 8, ...common });
  return { root, cpg, taint, delta, ctx:{root, budgetTokens:10000}, args:{path:'src/a.js', sourceNames:['readInput'], sinkNames:['send'], depth:20} };
}
async function G(source){ const f=setup(source); const r=await f.cpg.invoke('cpg.build',{path:'src/a.js'},f.ctx); return {f,g:JSON.parse(readFileSync(r.refs[0].path,'utf8')),r}; }
async function T(source, extra={}){ const f=setup(source); return f.taint.invoke('cpg.taint',{...f.args,...extra},f.ctx); }

