{
  const r = await T(`function readInput(){} function send(v){}
function run(){ let value; if(((/*a*/true/*b*/))){ value=1 } else { value=readInput() } send(value) }\n`);
  console.log('2 multi-paren comment true:', r.payload.length);
}

