{
  const r = await T(`function readInput(){} function send(v){}
function run(flag){ let value; if(flag) value=readInput(); send(value) }\n`);
  console.log('3 unbraced if may-flow:', r.payload.length);
}

// 4. if without else, false path preserves pre-def
{
  const r = await T(`function readInput(){} function safe(){} function send(v){}
function run(flag){ let value=readInput(); if(flag){ value=safe() } send(value) }\n`);
  console.log('4 no-else may path:', r.payload.length, r.payload[0]?.edgeTypes);
}

// 5. Both branches define different - may both reach?
{
  const f = setup(`function readInput(){} function safe(){} function send(v){}
function run(flag){ let value; if(flag){ value=readInput() } else { value=safe() } send(value) }\n`);
  const g = JSON.parse(readFileSync((await f.cpg.invoke('cpg.build',{path:'src/a.js'},f.ctx)).refs[0].path,'utf8'));
