  assert.equal(result.provenance.meaning, 'cfg_may_reach_value_graph_not_safety_proof');

  const heap = fixture(`function readInput(){} function send(v){} function run(o){ o.x=readInput(); send(o.x) }\n`);
  assert.equal((await heap.taint.invoke('cpg.taint', heap.args, heap.ctx)).payload.length, 0);
  const returned = fixture(`function readInput(){} function wrap(){ return readInput() } function send(v){} function run(){ send(wrap()) }\n`);
  assert.equal((await returned.taint.invoke('cpg.taint', returned.args, returned.ctx)).payload.length, 0);
});

    90|test('PS1/PS4: unsupported control remains atomic instead of making its nested values unreachable', async () => {
  const f = fixture(`function readInput(){} function send(v){}\nfunction run(){ let value; try { value=readInput() } catch {} send(value) }\n`);
  const result = await f.taint.invoke('cpg.taint', f.args, f.ctx);
  assert.equal(result.payload.length, 1);
});

test('PS1/PS2/PS4: an else-if chain is entered from the outer false edge and preserves the middle-arm may-flow', async () => {
  const f = fixture(`function readInput(){} function safe(){} function send(v){}\nfunction run(flag){
  let value
  if(flag === 1){
   100|    value=safe()
  } else if(flag === 2){
    value=readInput()
  } else {
    value=safe()
  }
  send(value)
}\n`);
  const g = await graph(f); const branches = g.nodes.filter((node) => node.type === 'statement' && node.kind === 'if_statement').sort((a, b) => a.range.start.line - b.range.start.line);
  assert.equal(branches.length, 2);
   110|  assert.ok(g.edges.some((edge) => edge.type === 'CFG_FALSE' && edge.from === branches[0].id && edge.to === branches[1].id));
  assert.equal(branches[1].cfgReachable, true);
  const result = await f.taint.invoke('cpg.taint', f.args, f.ctx);
  assert.equal(result.payload.length, 1);
});

test('PS1/PS4: a structured if inside atomic unsupported control collapses outward without reviving a literal-dead arm', async () => {
  const possible = fixture(`function readInput(){} function send(v){}\nfunction run(flag){ let value; try { if(flag){ value=readInput() } } catch {} send(value) }\n`);
  assert.equal((await possible.taint.invoke('cpg.taint', possible.args, possible.ctx)).payload.length, 1);
  const dead = fixture(`function readInput(){} function send(v){}\nfunction run(){ let value; try { if(false){ value=readInput() } } catch {} send(value) }\n`);
   120|  assert.equal((await dead.taint.invoke('cpg.taint', dead.args, dead.ctx)).payload.length, 0);
});

test('PS2/PS4: multiple same-name definitions collapsed into one atomic region remain a may-union', async () => {
  const f = fixture(`function readInput(){} function safe(){} function send(v){}\nfunction run(flag){ let value; switch(flag){ case 1: value=readInput(); break; default: value=safe() } send(value) }\n`);
  assert.equal((await f.taint.invoke('cpg.taint', f.args, f.ctx)).payload.length, 1);
});

test('PS1/PS4: AST boolean literals prune comment-bearing dead arms and emit no dead-tail join edge', async () => {
  const trueCase = fixture(`function readInput(){} function send(v){}\nfunction run(){ let value; if(/*lead*/true/*tail*/){ value=1 } else { value=readInput() } send(value) }\n`);
   130|  assert.equal((await trueCase.taint.invoke('cpg.taint', trueCase.args, trueCase.ctx)).payload.length, 0);
  const falseCase = fixture(`function readInput(){} function send(v){}\nfunction run(){ let value; if(false/*tail*/){ value=readInput() } send(value) }\n`);
  assert.equal((await falseCase.taint.invoke('cpg.taint', falseCase.args, falseCase.ctx)).payload.length, 0);
  const g = await graph(falseCase); const dead = g.nodes.find((node) => node.type === 'statement' && node.range.start.line === 2 && node.kind === 'expression_statement' && node.cfgReachable === false);
  assert.ok(dead); assert.equal(g.edges.some((edge) => ['CFG_NEXT', 'CFG_EXIT'].includes(edge.type) && edge.from === dead.id), false);
});

