cd /private/tmp/baton-cpg-closure-review.rYRa1L/.baton/wt/grok-cpg-impl-review-composer && node --input-type=module -e "
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { AtlasCpgSlice, AtlasCpgTaint } from './impl/src/index.mjs';

const dir = () => mkdtempSync(join(tmpdir(), 'probe-'));
async function probe(name, source, opts={}) {
  const root = dir(); const artifacts = dir();
  mkdirSync(join(root,'src'),{recursive:true});
  writeFileSync(join(root,'src/a.js'), source);
  const common = { maxSourceBytes: 65536, maxReachDefPairs: 4096, ...opts };
  const cpg = new AtlasCpgSlice({ artifactRoot: join(artifacts,'c'), maxArtifactBytes: 524288, ...common });
  const taint = new AtlasCpgTaint({ artifactRoot: join(artifacts,'t'), maxGraphBytes: 524288, maxResultBytes: 524288, maxDepth:24, maxPaths:32, ...common });
  const ctx = { root, budgetTokens: 10000 };
  const g = JSON.parse(readFileSync((await cpg.invoke('cpg.build',{path:'src/a.js'},ctx)).refs[0].path,'utf8'));
  const t = await taint.invoke('cpg.taint',{path:'src/a.js',sourceNames:['readInput'],sinkNames:['send'],depth:20},ctx);
  return { name, paths: t.payload.length, edges: g.edges, nodes: g.nodes };
}

const probes = [
  ['if-no-else', \`function readInput(){} function send(v){} function run(f){ let v; if(f){ v=readInput() } send(v) }\`],
  ['paren-false', \`function readInput(){} function send(v){} function run(){ let v; if((false)){ v=readInput() } send(v) }\`],
  ['else-if-unbraced', \`function readInput(){} function send(v){} function run(f){ let v; if(f){} else if(f) v=readInput(); send(v) }\`],
  ['shadow-inner', \`function readInput(){} function safe(){} function send(v){} function run(f){ let x=safe(); if(f){ let x=readInput() } send(x) }\`],
  ['unbraced-if', \`function readInput(){} function send(v){} function run(f){ let v; if(f) v=readInput(); else v=safe(); send(v) }\`],
];
for (const [name, src] of probes) {
  const r = await probe(name, src);
  const branch = r.nodes.filter(n=>n.type==='statement'&&n.kind==='if_statement');
  const cfg = r.edges.filter(e=>['CFG_TRUE','CFG_FALSE','CFG_NEXT'].includes(e.type));
  console.log('---', name, 'paths', r.paths, 'ifs', branch.length, 'cfg', cfg.length);
}
"

