import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { AtlasCpgSlice, AtlasCpgTaint } from './impl/src/index.mjs';

const dir = () => mkdtempSync(join(tmpdir(), 'probe-'));
async function build(source) {
  const root = dir(); const artifacts = dir();
  mkdirSync(join(root,'src'),{recursive:true});
  writeFileSync(join(root,'src/a.js'), source);
  const cpg = new AtlasCpgSlice({ artifactRoot: artifacts, maxSourceBytes: 65536, maxArtifactBytes: 524288, maxReachDefPairs: 4096 });
  const ctx = { root, budgetTokens: 10000 };
  return JSON.parse(readFileSync((await cpg.invoke('cpg.build',{path:'src/a.js'},ctx)).refs[0].path,'utf8'));
}

// if-no-else: only readInput def in then branch - does it reach send on false-only path?
const g1 = await build(\`function readInput(){} function send(v){} function run(f){ let v; if(f){ v=readInput() } send(v) }\`);
const readDef = g1.nodes.find(n=>n.type==='identifier'&&n.name==='v'&&n.role==='definition'&&n.range.start.line===2);
const readRef = g1.nodes.find(n=>n.type==='identifier'&&n.name==='v'&&n.role==='reference'&&n.range.start.line===2);
const sendRef = g1.nodes.find(n=>n.type==='identifier'&&n.name==='v'&&n.role==='reference'&&n.range.start.line===2);
console.log('if-no-else REACHING_DEF', g1.edges.filter(e=>e.type==='REACHING_DEF'&&e.to.includes('identifier')).map(e=>({from:e.from.slice(-20),to:e.to.slice(-20)})));

// shadow: which def reaches send x?
const g2 = await build(\`function readInput(){} function safe(){} function send(v){} function run(f){ let x=safe(); if(f){ let x=readInput() } send(x) }\`);
const reachX = g2.edges.filter(e=>e.type==='REACHING_DEF').map(e=>{
  const to = g2.nodes.find(n=>n.id===e.to);
  const from = g2.nodes.find(n=>n.id===e.from);
  return {fromLine: from?.range?.start?.line, fromName: from?.name, toLine: to?.range?.start?.line};
});
console.log('shadow REACHING_DEF', reachX);

