const done = g.nodes.find(n=>n.type==='statement'&&n.textDigest&&g.nodes.filter(x=>x.type==='call'&&x.calleeName==='done').length);
console.log('empty-then', g.edges.filter(e=>e.from===ifs?.id||e.to===ifs?.id));

// maxReachDef work before fail - time tiny ceiling on nasty input
const nasty = dir(); const art = dir();
mkdirSync(join(nasty,'src'),{recursive:true});
writeFileSync(join(nasty,'src/a.js'), 'function f(){'+Array.from({length:200},(_,i)=>'let v'+i+'=v'+(i-1)+';').join('')+'}');
const cpg2 = new AtlasCpgSlice({ artifactRoot: art, maxSourceBytes: 65536, maxArtifactBytes: 524288, maxReachDefPairs: 5 });
const t0 = Date.now();
try { await cpg2.invoke('cpg.build',{path:'src/a.js'},{root:nasty,budgetTokens:10000}); } catch(e) { console.log('ceiling', e.code, 'ms', Date.now()-t0); }

// delta reaching_def impact
const beforeRoot = dir(); const afterRoot = dir(); const dArt = dir();
const before = 'function run(f){ let v; if(f){ v=1 } else { v=2 } send(v) }';
const after = 'function run(f){ let v; if(f){ v=1 } send(v) }';
mkdirSync(join(beforeRoot,'src'),{recursive:true}); mkdirSync(join(afterRoot,'src'),{recursive:true});
