const artf = JSON.parse(readFileSync(dr.refs[0].path,'utf8'));
console.log('delta reachdef edges changed', artf.edgeChanges.filter(e=>e.type==='REACHING_DEF').length);
console.log('delta impact def_use', artf.impact.filter(i=>i.reason==='def_use').length);
"

